27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
31	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
36	import org.springframework.samples.petclinic.mapper.OwnerMapper;
37	import org.springframework.samples.petclinic.mapper.PetMapper;
38	import org.springframework.samples.petclinic.mapper.VisitMapper;
39	import org.springframework.samples.petclinic.model.Owner;
40	import org.springframework.samples.petclinic.model.Pet;
41	import org.springframework.samples.petclinic.model.Visit;
42	import org.springframework.samples.petclinic.rest.api.OwnersApi;
43	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
44	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.PetDto;
46	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
49	import org.springframework.samples.petclinic.service.ClinicService;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.util.StringUtils;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /**
69	     * Syntactic email check: a non-empty local part, an {@code @}, and a dotted domain, with no
70	     * whitespace or additional {@code @} characters. Deliberately permissive - it enforces basic
71	     * address shape rather than full RFC 5322 conformance.
72	     */
73	    private static final Pattern EMAIL_PATTERN =
74	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
75	
76	    /**
77	     * Common street-type abbreviations expanded during address normalization. Keys and values are
78	     * upper-cased so the mapping is applied after the address has been upper-cased.
79	     */
80	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
81	        "ST", "STREET",
82	        "RD", "ROAD",
83	        "AVE", "AVENUE");
84	
85	    /**
86	     * Maximum number of owners permitted in a single city. Once a city already contains this many
87	     * owners, creating another owner in that city is rejected as a conflict.
88	     */
89	    private static final int CITY_CAPACITY = 50;
90	
91	    /**
92	     * Maximum number of owners permitted to be registered on a single day. Once this many owners
93	     * already share the current registration date, creating another owner today is rejected.
94	     */
95	    private static final int DAILY_OWNER_LIMIT = 100;
96	
97	    private final ClinicService clinicService;
98	
99	    private final OwnerMapper ownerMapper;
100	
101	    private final PetMapper petMapper;
102	
103	    private final VisitMapper visitMapper;
104	
105	    public OwnerRestControllerV1(ClinicService clinicService,
106	                                 OwnerMapper ownerMapper,
107	                                 PetMapper petMapper,
108	                                 VisitMapper visitMapper) {
109	        this.clinicService = clinicService;
110	        this.ownerMapper = ownerMapper;
111	        this.petMapper = petMapper;
112	        this.visitMapper = visitMapper;
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
118	        Collection<Owner> owners;
119	        if (lastName != null) {
120	            owners = this.clinicService.findOwnerByLastName(lastName);
121	        } else {
122	            owners = this.clinicService.findAllOwners();
123	        }
124	        if (owners.isEmpty()) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
128	    }
129	
130	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
131	    @Override
132	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
133	        Owner owner = this.clinicService.findOwnerById(ownerId);
134	        if (owner == null) {
135	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
136	        }
137	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
138	    }
139	
140	    /**
141	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
142	     * upper-cases the value, and expands common street-type abbreviations word-by-word
143	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
144	     * normalizes to the empty string. The normalized value is what the application stores, returns
145	     * and compares for household detection.
146	     *
147	     * @param address the raw address value from the request, may be {@code null}
148	     * @return the normalized address, or the empty string when none was supplied
149	     */
150	    private String normalizeAddress(String address) {
151	        if (address == null) {
152	            return "";
153	        }
154	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
155	        if (collapsed.isEmpty()) {
156	            return "";
157	        }
158	        String[] tokens = collapsed.split(" ");
159	        StringBuilder normalized = new StringBuilder();
160	        for (int i = 0; i < tokens.length; i++) {
161	            if (i > 0) {
162	                normalized.append(' ');
163	            }
164	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
165	        }
166	        return normalized.toString();
167	    }
168	
169	    /**
170	     * Rejects an owner payload that is missing or blank in any required field. The response body's
171	     * {@code errors} array lists the name of each offending field.
172	     *
173	     * @param ownerFieldsDto the owner payload to validate
174	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
175	     */
176	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
177	        List<String> missingFields = new ArrayList<>();
178	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
179	            missingFields.add("firstName");
180	        }
181	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
182	            missingFields.add("lastName");
183	        }
184	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
185	            missingFields.add("address");
186	        }
187	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
188	            missingFields.add("city");
189	        }
190	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
191	            missingFields.add("telephone");
192	        }
193	        if (!missingFields.isEmpty()) {
194	            throw new RequiredFieldsMissingException(missingFields);
195	        }
196	    }
197	
198	    /**
199	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
200	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
201	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
202	     * followed by 8 to 15 digits.
203	     *
204	     * @param telephone the raw telephone value from the request
205	     * @return the E.164 telephone (e.g. {@code +61412345678})
206	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
207	     */
208	    private String normalizeTelephone(String telephone) {
209	        if (telephone == null) {
210	            throw new InvalidFieldsException(List.of("telephone"));
211	        }
212	        String trimmed = telephone.trim();
213	        boolean international = trimmed.startsWith("+");
214	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
215	        String digits;
216	        if (international) {
217	            digits = cleaned.substring(1);
218	        } else {
219	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
220	            digits = "61" + national;
221	        }
222	        if (!digits.matches("[0-9]{8,15}")) {
223	            throw new InvalidFieldsException(List.of("telephone"));
224	        }
225	        return "+" + digits;
226	    }
227	
228	    /**
229	     * Best-effort normalization of an existing owner's stored telephone into E.164 form for
230	     * duplicate comparison, returning {@code null} when the value cannot form valid E.164.
231	     *
232	     * @param telephone an existing stored telephone value, may be {@code null}
233	     * @return the E.164 form, or {@code null} when it cannot be normalized
234	     */
235	    private String toE164OrNull(String telephone) {
236	        if (telephone == null) {
237	            return null;
238	        }
239	        try {
240	            return normalizeTelephone(telephone);
241	        }
242	        catch (InvalidFieldsException ex) {
243	            return null;
244	        }
245	    }
246	
247	    /**
248	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
249	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
250	     * be a syntactically valid address; the accepted value is returned lower-cased.
251	     *
252	     * @param email the raw email value from the request, may be {@code null}
253	     * @return the lower-cased email, or {@code null} when none was supplied
254	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
255	     */
256	    private String normalizeEmail(String email) {
257	        if (email == null || email.isBlank()) {
258	            return null;
259	        }
260	        String trimmed = email.trim();
261	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
262	            throw new InvalidFieldsException(List.of("email"));
263	        }
264	        return trimmed.toLowerCase(Locale.ROOT);
265	    }
266	
267	    /**
268	     * Rejects a telephone that, once normalized, is already used by any existing owner. Existing
269	     * owners' telephones are normalized the same way before comparison so differently-formatted
270	     * values representing the same number are treated as duplicates.
271	     *
272	     * @param telephone the normalized (E.164) telephone of the owner being created
273	     * @throws DuplicateOwnerTelephoneException if another owner already uses the telephone
274	     */
275	    private void requireUniqueTelephone(String telephone) {
276	        boolean taken = this.clinicService.findAllOwners().stream()
277	            .map(Owner::getTelephone)
278	            .map(this::toE164OrNull)
279	            .filter(existing -> existing != null)
280	            .anyMatch(telephone::equals);
281	        if (taken) {
282	            throw new DuplicateOwnerTelephoneException(telephone);
283	        }
284	    }
285	
286	    /**
287	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
288	     * fields (last name, address) can be compared case-insensitively with collapsed whitespace. A
289	     * {@code null} value normalizes to the empty string.
290	     *
291	     * @param value the raw field value, may be {@code null}
292	     * @return the trimmed, whitespace-collapsed, lower-cased form
293	     */
294	    private String normalizeHousehold(String value) {
295	        if (value == null) {
296	            return "";
297	        }
298	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
299	    }
300	
301	    /**
302	     * Rejects an owner whose last name and address already match another owner (compared
303	     * case-insensitively with collapsed whitespace) - i.e. they would share a household - unless the
304	     * request opts in via {@code sharesHousehold}. Existing owners' fields are normalized the same
305	     * way before comparison.
306	     *
307	     * @param lastName the last name of the owner being created
308	     * @param address the address of the owner being created
309	     * @throws DuplicateOwnerHouseholdException if another owner shares the household
310	     */
311	    private void requireUniqueHousehold(String lastName, String address) {
312	        String normalizedLastName = normalizeHousehold(lastName);
313	        String normalizedAddress = normalizeHousehold(address);
314	        boolean shared = this.clinicService.findAllOwners().stream()
315	            .anyMatch(existing -> normalizeHousehold(existing.getLastName()).equals(normalizedLastName)
316	                && normalizeHousehold(existing.getAddress()).equals(normalizedAddress));
317	        if (shared) {
318	            throw new DuplicateOwnerHouseholdException(lastName, address);
319	        }
320	    }
321	
322	    /**
323	     * Rejects an owner whose city already contains the maximum permitted number of owners
324	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
325	     * the same normalization used for the other owner household fields.
326	     *
327	     * @param city the city of the owner being created
328	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
329	     */
330	    private void requireCityHasCapacity(String city) {
331	        String normalizedCity = normalizeHousehold(city);
332	        long count = this.clinicService.findAllOwners().stream()
333	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
334	            .count();
335	        if (count >= CITY_CAPACITY) {
336	            throw new CityAtCapacityException(city);
337	        }
338	    }
339	
340	    /**
341	     * Rejects creating an owner once the current day has already reached the maximum permitted
342	     * number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are counted by
343	     * their {@code registrationDate} against today's date.
344	     *
345	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
346	     *     registered today
347	     */
348	    private void requireDailyLimitNotReached() {
349	        LocalDate today = LocalDate.now();
350	        long count = this.clinicService.findAllOwners().stream()
351	            .filter(existing -> today.equals(existing.getRegistrationDate()))
352	            .count();
353	        if (count >= DAILY_OWNER_LIMIT) {
354	            throw new DailyOwnerLimitException(today);
355	        }
356	    }
357	
358	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
359	    @Override
360	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
361	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
362	        validateRequiredFields(ownerFieldsDto);
363	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
364	        requireUniqueTelephone(telephone);
365	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
366	            requireUniqueHousehold(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
367	        }
368	        requireCityHasCapacity(ownerFieldsDto.getCity());
369	        requireDailyLimitNotReached();
370	        String email = normalizeEmail(ownerFieldsDto.getEmail());
371	        HttpHeaders headers = new HttpHeaders();
372	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
373	        owner.setTelephone(telephone);
374	        owner.setEmail(email);
375	        if (owner.getRegistrationDate() == null) {
376	            owner.setRegistrationDate(LocalDate.now());
377	        }
378	        this.clinicService.saveOwner(owner);
379	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
380	        headers.setLocation(UriComponentsBuilder.newInstance()
381	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
382	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
383	    }
384	
385	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
386	    @Override
387	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
388	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
389	        if (currentOwner == null) {
390	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
391	        }
392	        currentOwner.setAddress(ownerFieldsDto.getAddress());
393	        currentOwner.setCity(ownerFieldsDto.getCity());
394	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
395	        currentOwner.setLastName(ownerFieldsDto.getLastName());
396	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
397	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
398	        this.clinicService.saveOwner(currentOwner);
399	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
400	    }
401	
402	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
403	    @Transactional
404	    @Override
405	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
406	        Owner owner = this.clinicService.findOwnerById(ownerId);
407	        if (owner == null) {
408	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
409	        }
410	        this.clinicService.deleteOwner(owner);
411	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
412	    }
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Override
416	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
417	        Owner owner = this.clinicService.findOwnerById(ownerId);
418	        if (owner == null) {
419	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
420	        }
421	        HttpHeaders headers = new HttpHeaders();
422	        Pet pet = petMapper.toPet(petFieldsDto);
423	        owner.setId(ownerId);
424	        pet.setOwner(owner);
425	        pet.getType().setName(null);
426	        this.clinicService.savePet(pet);
427	        PetDto petDto = petMapper.toPetDto(pet);
428	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
429	            .buildAndExpand(pet.getId()).toUri());
430	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Override
435	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
436	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
437	        if (currentOwner != null) {
438	            Pet currentPet = this.clinicService.findPetById(petId);
439	            if (currentPet != null) {
440	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
441	                currentPet.setName(petFieldsDto.getName());
442	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
443	                this.clinicService.savePet(currentPet);
444	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
445	            }
446	        }
447	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
448	    }
449	
450	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
451	    @Override
452	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
453	        HttpHeaders headers = new HttpHeaders();
454	        Visit visit = visitMapper.toVisit(visitFieldsDto);
455	        Pet pet = new Pet();
456	        pet.setId(petId);
457	        visit.setPet(pet);
458	        this.clinicService.saveVisit(visit);
459	        VisitDto visitDto = visitMapper.toVisitDto(visit);
460	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
461	            .buildAndExpand(visit.getId()).toUri());
462	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
463	    }
464	
465	
466	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
467	    @Override
468	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
469	        Owner owner = this.clinicService.findOwnerById(ownerId);
470	        if (owner != null) {
471	            Pet pet = owner.getPet(petId);
472	            if (pet != null) {
473	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
474	            }
475	        }
476	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
477	    }
478	}
